head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

//영문공시 번역지원 개발(유가)(20200904)
//SrM-000214854 개선사항 반영(20201204)
//SrM-000247674 코스닥 영문번역서비스 개발(20230224)
//현업이 직접 수정할수 있도록 함 (20220527)
//SrM-000249428 코스닥 법인 직접 입력, 코스닥 이메일 기능 추가(20230421)

scwin.gAcptNo;
scwin.gIsurCd;
scwin.gRdoMktId;
scwin.gDepCd = js_dep_cd;
scwin.gLdMktTp = js_market;
scwin.vScrenID = 'ULDSTF19000.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue(vCurDate); // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

    //현업이 직접 수정할수 있도록 함 20220527
    $c.stf.showObj(btn_isur_add, true);
    $c.stf.showObj(btn_form_add, true);
    $c.stf.showObj(btn_email, true);
    if (scwin.gLdMktTp == "1") {
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        $c.stf.showObj(panel_mkt, false);
        $c.stf.showObj(btn_email, false);
    } else if (scwin.gLdMktTp == "2") {
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        $c.stf.showObj(panel_mkt, false);
        $c.cm.setColumnProp(grd_Grid, 'CHRG1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG_NM1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'EMAIL1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CELLPHONE_NO1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG_NM3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'EMAIL3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CELLPHONE_NO3', 'Show', 'true');
    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, "1");
        $c.stf.showObj(panel_mkt, true);
        $c.cm.setColumnProp(grd_Grid, 'CHRG1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG_NM1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'EMAIL1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CELLPHONE_NO1', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CHRG_NM3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'EMAIL3', 'Show', 'true');
        $c.cm.setColumnProp(grd_Grid, 'CELLPHONE_NO3', 'Show', 'true');
    }
};
scwin.fn_CheckCond = function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }
    scwin.fn_Search();
};
scwin.fn_Search = function() {
    var url = "/DsclSearchAll.do?method=listEngTranslObjDiscls";
    url += "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate); //일자별
    url += "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate); //일자별
    url += "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID); //시장구분
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
    $c.cm.ShowWin(grd_Grid);
};



// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_DsclList.getCellData(eval(obj), "ISUR_CD");
};


//시장구분
scwin.fn_setMktId = function() {
    scwin.gRdoMktId = $c.stf.getObjectValue(rdo_MKT_ID);
};
scwin.IsurcdAdd = async function() {
    await $c.frame.CreateDialogFrame("virWinSave", "/dsclsrch/ULDSFT19000_POP.gfm", "영문번역대상법인 추가", js_com_left, js_com_top, 490, 570, "tool");
};
scwin.formAdd = async function() {
    await $c.frame.CreateDialogFrame("virWinSave", "/dsclsrch/ULDSFT19000_FORM.gfm", "영문번역대상서식 추가", js_com_left, js_com_top, 490, 570, "tool");
};


//메일발송
scwin.sendMail = function() {
    var url = "";
    url = "/dsclsrch/ULDSTF19000_EMAIL.gfm?";
    url += "frameID=" + frame.FrameID;
    $c.frame.path("../../").GWinOpen("ULDSFT19000", url, "이메일 발송", 200, 10, 700, 660, "");

    //frame.CreateDialogFrame("virWinMail",  "/dsclsrch/ULDSFT19000_EMAIL.gfm" , "이메일 발송", js_com_left, js_com_top, 800, 760, "tool");

};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_CheckCond();
};
scwin.dts_DsclList_OnLoadError = function() {
    $c.win.alert(dts_DsclList.errorMsg);
};
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.btn_Excel_onclick = function() {
    if (scwin.gLdMktTp == "1") {
        $c.data.downloadGridViewExcel(grd_Grid, "번역지원목록", "", "8");
    } else {
        $c.data.downloadGridViewExcel(grd_Grid, "번역지원목록", "", "2");
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R");
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_form_add_onclick = function() {
    //서식추가
    scwin.fn_setMktId();
    scwin.formAdd();
};
scwin.btn_isur_add_onclick = function() {
    //회사추가
    scwin.fn_setMktId();
    scwin.IsurcdAdd();
};
scwin.btn_email_onclick = function() {
    //메일발송
    scwin.fn_setMktId();
    scwin.sendMail();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.fn_CheckCond();
};
